head.script:
scwin.makeDataList = function(id, obj) {
    //create({ //정상
    $p.data.create({ //비정상
        "id": id,
        "type": "dataList",
        "option": {
            "useData": false
        },
        "columnInfo": obj
    });
}
scwin.onpageload = function() {
    var jsonData = [{
            "value": "a",
            "label": "test1"
        },
        {
            "value": "b",
            "label": "test2"
        },
        {
            "value": "c",
            "label": "test3"
        }
    ];
    var column = {};
    var columnArr = [];
    for (var k in jsonData[0]) {
        //dataList를 동적으로 만들기 위한 컬럼 정
        column = {};
        column["id"] = k;
        column["dataType"] = "text";
        columnArr.push(column);
    }
    scwin.makeDataList("dataList1", columnArr);
    dataList1.setJSON(jsonData);
    dataList2.setJSON(jsonData)
};
scwin.onpageunload = function() {};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'select1_label').innerText == 'test1'", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
